import{_ as t}from"./chunks/edit-event-quarantine.BYKwUhxF.js";import{c as s,Q as a,j as n,m as r}from"./chunks/framework.BqPkuuVc.js";const o="/assets/spectator-class-results-withheld.B-Rxgo-e.png",i="/assets/leaderboard-results-withheld.D7gvEwjM.png",l="/assets/info-pending-downloads-sign-in.2PTY6acV.png",y=JSON.parse('{"title":"Results quarantine","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/results-quarantine.md","filePath":"user/event-setup/results-quarantine.md"}'),h={name:"user/event-setup/results-quarantine.md"};function c(d,e,u,g,p,m){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="results-quarantine" tabindex="-1">Results quarantine <a class="header-anchor" href="#results-quarantine" aria-label="Permalink to &quot;Results quarantine&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers running a competition where some classes — usually the elite classes — start from a quarantine.</p><p>When runners wait in quarantine before their <a href="./../getting-started/concepts-glossary">start</a>, they must not learn anything about the course from the people who have already run it. Manager helps by holding back those classes&#39; <strong>results</strong> from every public display until you release them. The start list stays visible the whole time, so a spectator can still find out when an elite runner is due to start.</p><h2 id="what-is-held-back-and-where" tabindex="-1">What is held back, and where <a class="header-anchor" href="#what-is-held-back-and-where" aria-label="Permalink to &quot;What is held back, and where&quot;">​</a></h2><p>While a class is quarantined:</p><table tabindex="0"><thead><tr><th>Where</th><th>What it shows for that class</th></tr></thead><tbody><tr><td><strong><a href="./../screens/spectator-site-and-kiosk">Spectator site</a></strong> (phones)</td><td>The start list. Live results show <em>&quot;Results will be shown from 11:34.&quot;</em> instead of a result table.</td></tr><tr><td><strong>Kiosk</strong></td><td>The same as the spectator site.</td></tr><tr><td><strong>TV screens</strong> (<a href="./../screens/leaderboard#results-quarantine">leaderboard</a>, Live top 10, analysis walls)</td><td>The same notice where the class&#39;s table or graph would be.</td></tr><tr><td><strong>Results, analysis and splits pages</strong></td><td>The same notice in place of the class&#39;s results, graphs and splits.</td></tr><tr><td><strong>liveresultat</strong></td><td>The start list: each runner and their start time, shown as not started. No splits and no finish times.</td></tr><tr><td><strong>Live export</strong> (the IOF XML file written for other software)</td><td>The class is left out of the file.</td></tr></tbody></table><p>What is <strong>not</strong> affected, so your officials can still do their jobs:</p><ul><li><strong>Manager itself</strong>, on the operator&#39;s computer and the entry desk — you always see everything.</li><li><strong>The commentary screen</strong> — the speaker sees every result. Make sure whatever they read out can&#39;t be heard from the quarantine.</li><li><strong>The info screens</strong> (start clock, starters, radio feed, pending downloads).</li><li><strong>Exports you make yourself</strong> (results files, Eventor upload). Exporting results during a quarantine is your decision. A cloud push is different — see <em>Cloud copies</em> below.</li></ul><p><img src="'+o+'" alt="A class held back on the spectator site on a phone: M21E, with &quot;Results will be shown from 11:34.&quot; in place of its results"></p><p><img src="'+i+'" alt="A leaderboard TV screen showing two classes: M21E held back with &quot;Results will be shown from 11:34.&quot;, and M20&#39;s results beside it as normal"></p><p>If you have set an <a href="./../reference/multi-operator-setup#the-public-on-the-same-network-the-access-pin">access PIN</a> (<strong>Settings → <a href="./../reference/settings#access-protection">Access protection</a></strong>), the commentary screen and the <a href="./../screens/info-screens">info screens</a> that show results ask for it while a class is in quarantine — only a device signed in with the PIN is shown a quarantined class&#39;s results. Anyone can choose <strong>Continue without the PIN</strong>; that screen then shows the class&#39;s start list, like a public screen. The start clock and the starters screen never ask.</p><p><img src="'+l+'" alt="An info screen asking for the PIN: This event is holding back some classes&#39; results. Enter the PIN to see them on this screen, or continue without it to see their start lists. Unlock, Continue without the PIN, and a link to the Spectator views"></p><p><strong>Set a PIN if the quarantine has to hold.</strong> Without one, Manager cannot tell your officials&#39; screens from anybody else&#39;s on the venue network, and goes by what each screen says it is.</p><p>When a class is released, every open public screen updates by itself within a second or two, and <a href="./../running-the-event/publishing-live-results">liveresultat</a> and the live export catch up on their next publish. Nobody needs to reload a screen.</p><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><ol><li>On the event dashboard, click <strong><a href="./create-event#editing-event-details">Event details</a></strong> at the top, and choose the <strong>Quarantine</strong> tab. Until you add a class it says <em>No class is in quarantine.</em></li><li>Pick a class from <strong>Add a class</strong>. Add each class that is in quarantine — or click <strong>Add all</strong> to add every class at once.</li><li>For each class, choose under <strong>Release</strong> when its results come out: <ul><li><strong>At last start</strong> — the results appear once the last runner in the class is due to start. This follows the start list: if you move a start time, the release moves with it.</li><li><strong>At a set time</strong> — the results appear at the <strong>Release time</strong> you type in, whatever the start list says. The dialog won&#39;t save a class set to this with no time.</li></ul></li><li>Click <strong>Save</strong>.</li></ol><p><img src="'+t+'" alt="The Quarantine tab: M21E released At last start, shown as Hidden until 11:34, and W21E released At a set time with a Release time of 11:30, then the Add a class picker and Add all"></p><p>Once saved, a class released at its last start shows when that is, worked out from the start list — for example <em>Hidden until 11:34</em>, or <em>Released at 11:34</em> once that time has passed.</p><p><strong>Example.</strong> W21E&#39;s last starter is at 11:34 and M21E&#39;s at 11:56.</p><ul><li>Set both to <strong>At last start</strong>, and W21E appears on the public screens at 11:34 and M21E at 11:56.</li><li>Or set both to <strong>At a set time</strong> of 11:30, and both appear at 11:30.</li></ul><p>You can mix the two: each class has its own setting.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li><strong>&quot;At last start&quot; uses the <em>allocated</em> start times</strong> — the start list, including a class or event mass start. A runner who is marked as not starting (DNS, not participating, cancelled) doesn&#39;t count. It never waits for someone who starts late.</li><li><strong>A runner with no start time doesn&#39;t count either.</strong> A late entry who hasn&#39;t been given a start time yet is left out: the class is released at the last start time on the start list. If you then give them a later start, the class is hidden again until that start.</li><li><strong>A relay</strong> set to <em>At last start</em> is released at its restart, when every runner still waiting is sent out. A relay with no restart stays hidden until you finish the event — its later legs go whenever the runner before them comes in, which nobody can know in advance. Set a time if you want it out sooner.</li><li><strong>Release times to the second.</strong> A last start at 11:34:30 is shown as <em>Results will be shown from 11:34:30</em>, so the notice is never earlier than the release.</li><li><strong>A class with no start times yet stays hidden.</strong> If you choose <em>At last start</em> for a class that has no start times — a punching start, say — Manager can&#39;t tell when to release it, so it keeps the results hidden until you finish the event. The Quarantine tab says <em>No start times</em> beside it. Set a time instead, or remove the class when you want its results out.</li><li><strong>Releasing early.</strong> To release a class straight away, remove it from the list (the <strong>×</strong> beside it) and click <strong>Save</strong>.</li><li><strong>A class you delete</strong> stays on the list as <em>A deleted class</em> until you remove it.</li><li><strong>Moving a start later puts a class back into quarantine.</strong> If you give a runner a start time after the release, the class is hidden again until that new last start.</li><li><strong>Finishing the event releases everything.</strong> So does abandoning it.</li><li><strong>Replaying an event</strong> runs the quarantine again, exactly as it happened on the day.</li><li><strong>Cloud copies.</strong> A copy of the event pushed to a cloud server keeps its quarantined classes hidden until the event is finished (or two days after the event date), and shows <em>Results are not being shown yet</em> rather than a time. A cloud server&#39;s clock may be in a different time zone, so it can&#39;t safely go by the time of day.</li><li><strong>Shared courses.</strong> If a quarantined class shares a course with a class that isn&#39;t quarantined, the other class&#39;s course comparisons (such as the time-lost analysis) are worked out from everyone on the course, including the quarantined runners. Elite courses are normally their own, so this rarely matters.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./start-times">Start times</a> — where a class&#39;s start times come from</li><li><a href="./create-event#quarantine">Creating an event</a> — the other Event details tabs</li><li><a href="./../screens/info-screens">Event info screens</a> — the start clock and other displays that keep showing everything</li><li><a href="./../reference/multi-operator-setup#the-public-on-the-same-network-the-access-pin">Multi-operator setup</a> — setting the access PIN</li><li><a href="./../running-the-event/publishing-live-results">Publishing live results online</a> — what liveresultat and the meshO cloud are sent for a quarantined class</li><li><a href="./../screens/spectator-site-and-kiosk#what-the-public-can-t-see">The spectator site and kiosk</a> — what else the public is never shown</li></ul>',25)])])}const b=s(h,[["render",c]]);export{y as __pageData,b as default};
